import difflib
class Truth:
    def __bool__(self):
        with open('value.txt') as f: return f.read(1) == '1'
class Item:
    def __hash__(self): return 1
    def __eq__(self, other): return Truth()
s=difflib.SequenceMatcher(lambda x: True, [Item()], [Item()])
print(s.find_longest_match())

import difflib
class Junk:
    def __bool__(self):
        with open('value.txt') as f: return f.read(1) != '1'
    def __call__(self, value): raise ValueError('must not call')
s=difflib.SequenceMatcher(Junk(), 'ab', 'ab')
print(s.find_longest_match())
